"""Derive SkyyHud/build_skyyhud_0.3.30.py from the LIVE SkyyHud 0.3.29 (build_skyyhud_0.3.29.py = the tools/deploy_set.py SET pin, generated by
tools/hud_0_3_29_patch.py - never edit a generated script, edit this patch). Every anchor is asserted; at the end every change is undone on a
copy and compared with 0.3.29 (nothing else changed; tools/soundpass_gen.Patch). Line endings kept.
Run:  python tools/hud_0_3_30_patch.py   then   python SkyyHud/build_skyyhud_0.3.30.py   (never --deploy)
Check: python SkyyHud/test_skyyhud_0.3.30.py [--dir <folder inside tools/dev/scratch/>] [--keep]
"""
import os, sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
sys.path.insert(0, os.path.join(ROOT, "tools"))
import soundpass_gen as G

NOTE = '''0.3.30 (2026-10-16) = LOG FIX (round logfix; Skyy's standing rule "check the logs after every play session, fix ours"). Live log
  2026-10-16 15:12 (Saves/NewBetaTest) at shutdown: "minimap: reaching the world thread to remove the minimap failed ...
  IllegalThreadStateException: World thread is not accepting tasks" - Minimap.detach (drop -> detach(s, "gone") / server stop) queued the
  HUD removal on a world whose thread had already stopped. Minimap.stopped(t) = the failure is (or wraps) an IllegalThreadStateException /
  "not accepting tasks": then there is nothing left to remove (the world and its HUDs are gone) - skipped quietly (no WARN, no error count).
  Any other failure is logged as before. Nothing else changed: no widget, file, command, permission or saved-data change. ROLLBACK to
  0.3.29: safe (only that shutdown WARN comes back).
'''

P = G.Patch(os.path.join(ROOT, "SkyyHud", "build_skyyhud_0.3.29.py"), os.path.join(ROOT, "SkyyHud", "build_skyyhud_0.3.30.py"))
assert P.has('VERSION = "0.3.29"') and P.has("class:fn:stacks") and not P.has("public static boolean stopped("), "not the generated SkyyHud 0.3.29 script"
REG0, SYS0 = P.s.count("registerCommand("), P.s.count("registerSystem(")

# ================================================================================================ docstring + version
P.rep('''"""SkyyHud 0.3.29 - build script (javassist via jpype). GENERATED by tools/hud_0_3_29_patch.py from the LIVE 0.3.28 - edit the patch.
Run:   python build_skyyhud_0.3.29.py            -> SkyyHud/SkyyHud-0.3.29.jar
       (deploys only through tools/deploy_set.py - never pass --deploy here)
Check: python SkyyHud/test_skyyhud_0.3.29.py
''', '''"""SkyyHud 0.3.30 - build script (javassist via jpype). GENERATED by tools/hud_0_3_30_patch.py from the LIVE 0.3.29 - edit the patch.
Run:   python build_skyyhud_0.3.30.py            -> SkyyHud/SkyyHud-0.3.30.jar
       (deploys only through tools/deploy_set.py - never pass --deploy here)
Check: python SkyyHud/test_skyyhud_0.3.30.py
''' + NOTE + '''0.3.29 (generated by tools/hud_0_3_29_patch.py from 0.3.28):
''')
P.rep('VERSION = "0.3.29"\n', 'VERSION = "0.3.30"\n')

# ================================================================================================ detach on a stopped world thread
P.rep('''MMM(mmmain, r"""
public static void detach(@PKG@.MmSess s, String why) {''', '''# 0.3.30: a failure that means the world thread no longer takes tasks (shutdown / world removed): an IllegalThreadStateException
# anywhere in the cause chain (the engine wraps it in a SkipSentryException) or its "not accepting tasks" text
MMM(mmmain, r"""
public static boolean stopped(Throwable t) {
  Throwable c = t;
  for (int i = 0; i < 8 && c != null; i++) {
    if (c instanceof IllegalThreadStateException) return true;
    String m = c.getMessage();
    if (m != null && m.indexOf("not accepting tasks") >= 0) return true;
    c = c.getCause();
  }
  return false;
}""")
MMM(mmmain, r"""
public static void detach(@PKG@.MmSess s, String why) {''')
P.rep('''    try { s.world.execute(new @PKG@.MmDetach(s.pr, s.store, h)); } catch (Throwable t) { err("reaching the world thread to remove the minimap", t); }''',
      '''    try { s.world.execute(new @PKG@.MmDetach(s.pr, s.store, h)); } catch (Throwable t) { if (!stopped(t)) err("reaching the world thread to remove the minimap", t); }   // 0.3.30: a stopped world = nothing to remove''')

assert P.s.index("public static boolean stopped(") < P.s.index("public static void detach(@PKG@.MmSess s"), "stopped before its caller"
assert P.s.count("registerCommand(") == REG0 and P.s.count("registerSystem(") == SYS0, "command / system registrations changed"
P.finish()
